 <script>document.getElementById('shareButton').addEventListener('click',async()=>{const data={title:@json($business->cmpd_name),text:'View this business on Net-Works',url:location.href};if(navigator.share){await navigator.share(data)}else{await navigator.clipboard.writeText(location.href);const button=document.getElementById('shareButton');button.textContent='✓ Link copied';setTimeout(()=>button.textContent='↗ Share',1800)}})</script>
